<?php require 'autorizare.php';$rows=$pdo->query('SELECT c.titlu,SUM(v.nr_buc) bucati FROM vanzari v JOIN carti c ON c.id_carte=v.id_carte GROUP BY c.id_carte,c.titlu ORDER BY bucati DESC')->fetchAll();include 'admin_top.php';?><h2>Vanzari cumulate</h2><table border="1" cellpadding="5"><tr><th>Carte</th><th>Bucati</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['titlu'])?></td><td><?=(int)$r['bucati']?></td></tr><?php endforeach;?></table></body></html>
